 cnv_ban:{eDiv:5},           /* cnv_ban .7 x1 odds: Sủng (risen maid) or Chủ tin, divided by eDiv (RDQ.banRS) */
 cnv_mat:{tinDiv:5},         /* cnv_mat .10 c2 odds: Chủ tin / tinDiv while she is still a maid (RDQ.matTin) */
